import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String[] first = line.split(" ");
        int v = Integer.parseInt(first[0]);
        int e = Integer.parseInt(first[1]);

        if (e == 0) {
            System.out.println(0);
            return;
        }
        if (v <= 6) {
            System.out.println(e);
            return;
        }

        List<Integer>[] adj = new List[v + 1];
        for (int i = 1; i <= v; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < e; i++) {
            line = br.readLine();
            if (line == null) break;
            String[] edge = line.split(" ");
            int a = Integer.parseInt(edge[0]);
            int b = Integer.parseInt(edge[1]);
            adj[a].add(b);
            adj[b].add(a);
        }

        boolean f = false;
        int noOfVertices = 20;

        for (int j = 1; j <= 7; j++) {
            List<Integer> a7 = adj[j];
            for (int i = 1; i <= 7; i++) {
                if (i == j) continue;
                List<Integer> other = adj[i];
                Set<Integer> set = new HashSet<>(a7);
                int count = 0;
                for (int neighbor : other) {
                    if (set.contains(neighbor)) {
                        count++;
                    }
                }
                if (count == 0) {
                    f = true;
                    break;
                } else if (count < noOfVertices) {
                    noOfVertices = count;
                }
            }
            if (f) break;
        }

        if (f) {
            System.out.println(e);
        } else {
            System.out.println(e - noOfVertices);
        }
    }
}

